def test_ordering_with_isnull_lookup_no_error():
    from django.test.utils import isolate_apps
    from django.db import models
    from django.core import checks
    from django.conf import settings
    import django

    if not settings.configured:
        settings.configure(
            DATABASES={'default': {'ENGINE': 'django.db.backends.sqlite3'}},
            INSTALLED_APPS=['django.contrib.contenttypes', 'django.contrib.auth'],
        )
        django.setup()

    @isolate_apps('testapp')
    def run_test():
        class Product(models.Model):
            parent = models.ForeignKey('self', models.CASCADE, null=True)

            class Meta:
                app_label = 'testapp'

        class Supply(models.Model):
            product = models.ForeignKey(Product, on_delete=models.CASCADE)

            class Meta:
                app_label = 'testapp'

        class Stock(models.Model):
            supply = models.ForeignKey(Supply, on_delete=models.CASCADE)

            class Meta:
                app_label = 'testapp'
                ordering = ['supply__product__parent__isnull']

        errors = Stock.check()
        error_ids = [e.id for e in errors]
        # Under oracle patch: isnull is a valid lookup, no E015 error
        # Under suspicious patch: isnull is not recognized as transform, E015 is raised
        assert 'models.E015' not in error_ids, (
            f"Unexpected models.E015 error raised for valid 'isnull' lookup in ordering. "
            f"Errors: {errors}"
        )

    run_test()
